// Edit only these non-secret inputs. Keep credentials in n8n's credential store.
return [{ json: {
  video_url: '',
  summary_language: 'English',
  destination: 'notion', // 'notion' or 'sheets'
  run_key: '', // Stable, unique label for this intentional export, e.g. research-2026-11-07-01
  notion_parent_page_id: '', // Plain page UUID, not a database ID
  sheets_spreadsheet_id: '',
  sheets_tab: 'Transcripts'
} }];

const c = $input.first().json;
if ($input.all().length !== 1) throw new Error('Run one video per execution.');
if (typeof c.video_url !== 'string' || !/^https:\/\/(?:www\.|m\.)?(?:youtube\.com|youtu\.be)\//.test(c.video_url)) throw new Error('Set video_url to an HTTPS YouTube video URL.');
if (!['notion', 'sheets'].includes(c.destination)) throw new Error('destination must be notion or sheets.');
if (typeof c.run_key !== 'string' || !/^[A-Za-z0-9_-]{1,80}$/.test(c.run_key)) throw new Error('Set run_key to 1-80 letters, digits, underscores or hyphens. Check the destination for this key before running.');
const languages = ["Auto","English","Spanish","Hindi","Chinese","Arabic","French","Russian","Portuguese","Urdu","German","Japanese","Indonesian","Vietnamese","Korean","Turkish","Italian","Polish","Dutch","Persian","Bulgarian","Czech","Danish","Finnish","Greek","Hebrew","Hungarian","Malay","Norwegian","Romanian","Slovak","Swedish","Tagalog","Thai","Ukrainian","Bengali","Punjabi","Tamil","Telugu","Marathi","Gujarati","Kannada","Malayalam","Swahili","Afrikaans","Catalan","Croatian","Serbian","Slovenian","Lithuanian","Latvian","Estonian","Icelandic","Welsh","Albanian","Macedonian","Azerbaijani","Kazakh","Armenian","Georgian","Amharic","Nepali","Sinhala","Khmer","Burmese","Mongolian"];
if (!languages.includes(c.summary_language)) throw new Error('Use an exact supported language name such as English, Spanish, or Auto, not a language code.');
if (c.destination === 'notion' && !/^(?:[a-f0-9]{32}|[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})$/i.test(c.notion_parent_page_id)) throw new Error('Set notion_parent_page_id to a page UUID.');
if (c.destination === 'sheets' && (!/^[A-Za-z0-9_-]+$/.test(c.sheets_spreadsheet_id) || typeof c.sheets_tab !== 'string' || !c.sheets_tab.trim() || c.sheets_tab.length > 100)) throw new Error('Set sheets_spreadsheet_id and an existing sheets_tab (1-100 characters).');
return [{ json: c }];

const t = $input.first().json;
if (typeof t.transcript !== 'string' || !t.transcript || typeof t.video_id !== 'string' || !t.video_id || !(typeof t.video_title === 'string' || t.video_title === null) || typeof t.method !== 'string' || typeof t.cached !== 'boolean' || !Number.isFinite(t.credits_used)) throw new Error('Unexpected transcript response; stopping before summary billing.');
return [{ json: { ...$('Validate input').first().json, transcription: t } }];

const s = $input.first().json;
const c = $('Preserve transcript').first().json;
const t = c.transcription;
if (typeof s.summary !== 'string' || !s.summary || !(typeof s.video_id === 'string' || s.video_id === null) || !Number.isFinite(s.credits_used)) throw new Error('Unexpected JSON summary response; no destination writes attempted.');
const metadata = {
  run_key: c.run_key, video_url: c.video_url, video_id: t.video_id,
  video_title: t.video_title, method: t.method, cached: t.cached,
  transcript_credits_used: t.credits_used, summary_credits_used: s.credits_used,
  total_credits_used: t.credits_used + s.credits_used,
  summary_video_id: s.video_id, summary_language: c.summary_language
};
// Keep UTF-16 surrogate pairs together; joining chunks exactly reconstructs input.
function chunks(text, limit) {
  const out = [];
  for (let start = 0; start < text.length;) {
    let end = Math.min(start + limit, text.length);
    const last = text.charCodeAt(end - 1);
    if (end < text.length && last >= 0xD800 && last <= 0xDBFF) end--;
    out.push(text.slice(start, end));
    start = end;
  }
  return out;
}
const sections = [['metadata', JSON.stringify(metadata)], ['summary', s.summary], ['transcript', t.transcript]];
if (c.destination === 'notion') {
  const blocks = [];
  for (const [section, text] of sections) {
    blocks.push({ object: 'block', type: 'heading_2', heading_2: { rich_text: [{ type: 'text', text: { content: section } }] } });
    for (const textPart of chunks(text, 1600)) blocks.push({ object: 'block', type: 'paragraph', paragraph: { rich_text: [{ type: 'text', text: { content: textPart } }] } });
  }
  const batches = [];
  let batch = [], size = 0;
  // JSON UTF-16 length * 3 bounds UTF-8 bytes, including escaped control characters.
  // Leave ample space for parent/properties outside children; <=80 children per page.
  for (const block of blocks) {
    const blockSize = JSON.stringify(block).length + 1;
    if (batch.length && (batch.length >= 80 || size + blockSize > 140000)) {
      batches.push(batch); batch = []; size = 0;
    }
    batch.push(block); size += blockSize;
  }
  if (batch.length) batches.push(batch);
  return batches.map((children, index) => ({ json: {
    destination: 'notion', run_key: c.run_key, part: index + 1, parts: batches.length,
    body: { parent: { page_id: c.notion_parent_page_id }, properties: {
      title: { type: 'title', title: [{ type: 'text', text: { content: c.run_key + ' | ' + t.video_id + ' | part ' + (index + 1) + '/' + batches.length } }] }
    }, children }
  }, pairedItem: { item: 0 } }));
}
const rows = [];
for (const [section, text] of sections) {
  const parts = chunks(text, 40000);
  parts.forEach((part, index) => rows.push([c.run_key, t.video_id, section, index + 1, parts.length, part]));
}
// Bound request size as well as cell size. Multiple appends are explicitly numbered.
const batches = [];
let batch = [], size = 0;
for (const row of rows) {
  const rowSize = JSON.stringify(row).length + 1;
  if (batch.length && size + rowSize > 450000) { batches.push(batch); batch = []; size = 0; }
  batch.push(row); size += rowSize;
}
if (batch.length) batches.push(batch);
const range = "'" + c.sheets_tab.replace(/'/g, "''") + "'!A:F";
const url = 'https://sheets.googleapis.com/v4/spreadsheets/' + encodeURIComponent(c.sheets_spreadsheet_id) + '/values/' + encodeURIComponent(range) + ':append?valueInputOption=RAW&insertDataOption=INSERT_ROWS';
return batches.map((values, index) => ({ json: {
  destination: 'sheets', run_key: c.run_key, part: index + 1, parts: batches.length,
  url, body: { majorDimension: 'ROWS', values }
}, pairedItem: { item: 0 } }));
